using System.Text.Json;
using NexaStation.Core;
using NexaStation.Customization.Layouts;
using NexaStation.Customization.Models;
using NexaStation.Customization.Services;
using NexaStation.Customization.Themes;

namespace NexaStation.Customization.ImportExport;

public sealed class InterfaceConfigurationService(ICustomizationStore store,ISettingsService settings,IInterfaceLayoutService layouts,IThemeService themes,IPerformancePresetService performance):IInterfaceConfigurationService
{
    public const int CurrentFormatVersion=1;private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web){WriteIndented=true};
    public async Task<string> ExportAsync(CancellationToken cancellationToken=default){InterfaceConfigurationSnapshot snapshot=await CaptureAsync(cancellationToken);return JsonSerializer.Serialize(snapshot,JsonOptions);}
    public Task<InterfaceConfigurationPreview> PreviewImportAsync(string json,CancellationToken cancellationToken=default){try{InterfaceConfigurationSnapshot snapshot=Parse(json);List<string> warnings=[];if(snapshot.CustomTheme?.Background.Type==BackgroundType.Image)warnings.Add("Image backgrounds are imported only as existing NexaStation-managed references.");return Task.FromResult(new InterfaceConfigurationPreview(true,snapshot.Dashboards.Count,snapshot.Rows.Count,snapshot.Pins.Count,snapshot.Collections.Count,warnings));}catch(Exception ex) when(ex is JsonException or InvalidDataException or ArgumentException){return Task.FromResult(new InterfaceConfigurationPreview(false,0,0,0,0,[ex.Message]));}}
    public async Task<InterfaceConfigurationImportResult> ImportAsync(string json,CancellationToken cancellationToken=default)
    {
        try{InterfaceConfigurationSnapshot incoming=Parse(json);if((await layouts.GetAvailableAsync(cancellationToken)).All(x=>x.Id!=incoming.LayoutId))throw new InvalidDataException("The imported layout is not available.");IReadOnlyList<ThemeDefinition> availableThemes=await themes.GetAvailableAsync(cancellationToken);if(availableThemes.All(x=>x.Id!=incoming.ThemeId)&&incoming.CustomTheme?.Id!=incoming.ThemeId)throw new InvalidDataException("The imported theme is not available.");if(incoming.SoundPackId is not ("nexa-soft" or "minimal-click" or "silent" or "arcade-light"))throw new InvalidDataException("The imported sound pack is not available.");if(incoming.SoundVolume is <0 or >1)throw new InvalidDataException("The imported sound volume is outside the supported range.");string backup=await store.SaveExportBackupAsync(JsonSerializer.Serialize(await CaptureAsync(cancellationToken),JsonOptions),cancellationToken);await store.ApplySnapshotAsync(incoming,cancellationToken);await layouts.ApplyAsync(incoming.LayoutId,cancellationToken);if(incoming.CustomTheme is not null)await themes.SaveCustomAsync(incoming.CustomTheme,cancellationToken);await themes.ApplyAsync(incoming.ThemeId,cancellationToken);await settings.SetAsync("Interface.SoundPackId",incoming.SoundPackId,cancellationToken);await settings.SetAsync("Interface.SoundVolume",incoming.SoundVolume,cancellationToken);if(incoming.Performance.Preset==VisualPerformancePreset.Custom)await performance.SaveCustomAsync(incoming.Performance,cancellationToken);else await performance.ApplyAsync(incoming.Performance.Preset,incoming.Performance.ReducedMotion,cancellationToken);return new(true,backup,[]);}catch(Exception ex) when(ex is JsonException or InvalidDataException or ArgumentException or InvalidOperationException){return new(false,null,[ex.Message]);}
    }
    public async Task ResetAllAsync(CancellationToken cancellationToken=default){await store.SaveExportBackupAsync(await ExportAsync(cancellationToken),cancellationToken);await store.ClearInterfaceCustomizationAsync(cancellationToken);await layouts.ResetAsync(cancellationToken);await themes.ResetAsync(cancellationToken);await performance.ApplyAsync(VisualPerformancePreset.Balanced,false,cancellationToken);await settings.SetAsync("Interface.SoundPackId","nexa-soft",cancellationToken);await settings.SetAsync("Interface.SoundVolume",.6,cancellationToken);}
    private async Task<InterfaceConfigurationSnapshot> CaptureAsync(CancellationToken token)
    {
        List<DashboardConfiguration> dashboards=[];List<DashboardRowConfiguration> rows=[];foreach(InterfaceLayoutDefinition layout in await layouts.GetAvailableAsync(token)){DashboardConfiguration? dashboard=await store.GetDashboardAsync(layout.Id,token);if(dashboard is not null){dashboards.Add(dashboard);rows.AddRange(await store.GetRowsAsync(dashboard.Id,token));}}
        List<PinnedItem> pins=[];foreach(PinLocation location in Enum.GetValues<PinLocation>())pins.AddRange(await store.GetPinsAsync(location,token));IReadOnlyList<CollectionDefinition> collections=await store.GetCollectionsAsync(token);List<CollectionItem> items=[];List<SmartCollectionRule> rules=[];foreach(CollectionDefinition collection in collections){items.AddRange(await store.GetCollectionItemsAsync(collection.Id,token));rules.AddRange(await store.GetRulesAsync(collection.Id,token));}
        string themeId=await settings.GetAsync("Interface.ThemeId",ThemeService.DefaultThemeId,token);ThemeDefinition? custom=(await store.GetCustomThemesAsync(token)).FirstOrDefault(x=>x.Id==themeId);return new(CurrentFormatVersion,DateTime.UtcNow,layouts.CurrentLayoutId,dashboards,rows,pins,collections,items,rules,themeId,custom,await settings.GetAsync("Interface.SoundPackId","nexa-soft",token),await settings.GetAsync("Interface.SoundVolume",.6,token),await performance.GetAsync(token));
    }
    private static InterfaceConfigurationSnapshot Parse(string json)
    {
        if(string.IsNullOrWhiteSpace(json)||json.Contains("<script",StringComparison.OrdinalIgnoreCase)||json.Contains("javascript:",StringComparison.OrdinalIgnoreCase)||json.Contains("http://",StringComparison.OrdinalIgnoreCase)||json.Contains("https://",StringComparison.OrdinalIgnoreCase)||json.Contains("..\\",StringComparison.Ordinal)||json.Contains("../",StringComparison.Ordinal))throw new InvalidDataException("The interface configuration contains executable, external, or traversing content.");
        InterfaceConfigurationSnapshot snapshot=JsonSerializer.Deserialize<InterfaceConfigurationSnapshot>(json,JsonOptions)??throw new InvalidDataException("The interface configuration is empty.");if(snapshot.FormatVersion!=CurrentFormatVersion)throw new InvalidDataException($"Unsupported interface configuration version {snapshot.FormatVersion}.");if(!Enum.IsDefined(snapshot.Performance.Preset)||snapshot.Rows.Any(x=>!Enum.IsDefined(x.RowType)||!Enum.IsDefined(x.CardStyle)||!Enum.IsDefined(x.CardSize))||snapshot.SmartRules.Any(x=>!Enum.IsDefined(x.Field)||!Enum.IsDefined(x.Operator)))throw new InvalidDataException("The interface configuration contains an unknown enum value.");if(snapshot.CustomTheme is not null)ThemeService.Validate(snapshot.CustomTheme);return snapshot;
    }
}
